import re
from re import search
from contextlib import contextmanager
from functools import partial

from ute_fsmaccess.exception import SSHExecutionError, WrongPartition, UnknownFsmHwVersion


import tarfile
import os
import shutil
import tempfile
import glob

class EstablishSSHinMethodContext(object):
    """Establish ssh session within fsm_method context."""

    def __init__(self, fsm_method):
        self.fsm_method = fsm_method

    def __call__(self, *args, **kwargs):
        with self.establish_ssh(args[0]):
            return self.fsm_method(*args, **kwargs)

    def __get__(self, obj, objtype):
        """Support instance methods."""
        return partial(self.__call__, obj)

    @contextmanager
    def establish_ssh(self, fsm_access):
        """Setup and teardown ssh connection in specific context.

        :param fsm_access:      Fsm client.

        """
        try:
            if hasattr(fsm_access, "setup"):
                yield fsm_access.setup()
        finally:
            if hasattr(fsm_access, "teardown"):
                fsm_access.teardown()


class FsmAccess(object):
    ENB_BUILD_REGEXP = "(SBTS|[FT]L|5G)[0-9A-Z_\.]+"

    def __init__(self, connection_manager):
        """ Prepare connection to Fsm.

        :param connection_manager:      Connection manager.

        """
        self._fsm_connection_manager = connection_manager
        self._fsm_connection_client = None

    def setup(self, *args, **kwargs):
        """ Establish connection to Fsm.

        """
        self.teardown()
        self._fsm_connection_client = self._fsm_connection_manager.start()

    def teardown(self, *args, **kwargs):
        """ Close ssh connection to Fsm.

        """
        self._fsm_connection_manager.stop()
        self._fsm_connection_client = None

    @EstablishSSHinMethodContext
    def execute(self, command, return_rc=False):
        """ Execute shell command of Fsm.

        :param string command:      Shell command to be executed.
        :param bool   return_rc:    Flag for returning shell command rc. Default: False

        :return:                    Shell command output. If return_rc is True, also returns shell command rc.
        :rtype:                     string or (string, int)

        :raise:                     Exception if return code is not 0 and return_rc is False.
        """

        return self._execute_ssh_command(command, return_rc)

    @EstablishSSHinMethodContext
    def start_command(self, command):
        """ Write shell command of Fsm.Unlike to "execute command", "start command" does not
        wait for return code.

        :param string command:      Shell command to be started.

        """

        return self._fsm_connection_client.send_command(command)

    @EstablishSSHinMethodContext
    def get_fsm_file(self, src, dst):
        """Copy a given file from defined partition of FSM to specified localization on PC.

        :param string src:              Source file path.
        :param string dst:              Destination file path.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        return self._get_file(src=src, dst=dst)

    @EstablishSSHinMethodContext
    def put_fsm_file(self, src, dst, partition='active'):
        """Copy a given file from specified localization on PC to defined partition of FSM.

        :param string src:              Source file path.
        :param string dst:              Destination file path.
        :param string partition:        Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """
        if partition == 'passive':
            self._make_writeable_passive_partition()
        return self._put_file(src=src, dst=dst)

    @EstablishSSHinMethodContext
    def get_fsm_directory(self, src, tar_output):
        """Copy a given directory from defined partition of FSM to specified localization on PC

        :param src:             Source of directory to be copied
        :param tar_output:      Destination of tar output file

        :return tar_output:     returns the final tar output path
        :rtype: string

        :raises ValueError      raised when filename of tar_output is incorrect
        """
        if '.' not in tar_output:
            tar_output = '{}.tar.bz2'.format(tar_output)
        elif not tar_output.endswith('.tar.bz2'):
            raise ValueError('Tar output filename must end in .tar.bz2')
        self._get_directory(src=src, tar_output=tar_output)
        return tar_output

    @EstablishSSHinMethodContext
    def get_fsm_hw_version(self):
        """Get Fsm hardware version.

        :return:    Fsm hardware version (FSMr2/FSMr3/FSMr4/FSMr5) based on eNB main board type
        :rtype:     string

        :raise:     Exception if fsm hardware version is invalid
        """
        system_info = self._execute_ssh_command("cat /proc/device-tree/module-identity/unit-id").rstrip('\x00')
        versions_dict = {'FSME': 'FSMr2',
                         'FSMF': 'FSMr3', 'FSIH': 'FSMr3',
                         'ASIA': 'FSMr4', 'ASIB': 'FSMr4', 'FSIP': 'FSMr4', 'ABIA': 'FSMr4',
                         'ASIK': 'FSMr5', 'ABIL': 'FSMr5', 'ASOD': 'FSMr5',
                         'ASIL': 'FSMr6', 'ASOE': 'FSMr6', 'ASOF': 'FSMr6', 'ABIN': 'FSMr6', 'ABIO': 'FSMr6',
                         'ASIM': 'FSMr7', 'ABIP': 'FSMr7', 'ASOG': 'FSMr7', 'ASOH': 'FSMr7'}
        if system_info not in versions_dict:
            raise UnknownFsmHwVersion("Unknown FSM HW version: {sys_inf}".format(sys_inf=system_info))
        return versions_dict[system_info]

    @EstablishSSHinMethodContext
    def file_exists(self, target_file):
        """Check if given file exists on Fsm.

        :param string target_file:      File path.

        :return:                        True/False.
        :rtype:                         string

        """
        return self._execute_ssh_command('[ -f %s ] && echo True || echo False' % target_file) == 'True'

    @EstablishSSHinMethodContext
    def dir_exists(self, target_dir):
        """Check if given directory exists on Fsm.

        :param string target_dir:       Directory path.

        :return:                        True/False.
        :rtype:                         string
        """
        return self._execute_ssh_command('[ -d %s ] && echo True || echo False' % target_dir) == 'True'

    @EstablishSSHinMethodContext
    def get_partition_path(self, partition):
        """Get Fsm partition path.

        :param string partition:        Partition type.

        :return:                        Partition path.
        :rtype:                         String
        """
        return self._get_partition_path(partition)

    def _execute_ssh_command(self, command, return_rc=False):
        process_out = self._call_ssh_function(self._fsm_connection_client.send_command, command)
        out = process_out.read_output().strip()
        rc = process_out.get_exit_code()
        err = process_out.read_error().strip()
        if rc == 0 and out == '' and err != '':
            return (err, rc) if return_rc else err
        elif rc == 0:
            return (out, rc) if return_rc else out
        elif return_rc:
            return (err, rc)
        else:
            raise SSHExecutionError(err)

    def _get_fsm_sw_version(self, partition='active'):
        partition_path = self._get_partition_path(partition)
        try:
            sw_version = self._get_sw_version_via_targetbd(partition_path)
        except SSHExecutionError:
            sw_version = self._get_sw_version_via_filedirectory(partition_path)
        return sw_version

    def _get_sw_version_via_filedirectory(self, partition_path):
        filedir_regex = '(activeBuildVersion|activeBuildName)=\\"({})\\"'.format(FsmAccess.ENB_BUILD_REGEXP)
        command = 'grep -E "{}" {}/FileDirectory.xml'.format(filedir_regex, partition_path)
        result = self._execute_ssh_command(command)
        return self._get_sw_version_from_string(result)

    def _get_sw_version_via_targetbd(self, partition_path):
        command = 'ls -1 {}/TargetBD_*.xml | grep -E "{}"'.format(partition_path, FsmAccess.ENB_BUILD_REGEXP)
        target_bd = self._execute_ssh_command(command)
        target_bd = target_bd.replace(".xml", "")
        return self._get_sw_version_from_string(target_bd)

    def _get_sw_version_from_string(self, str):
        m = search(FsmAccess.ENB_BUILD_REGEXP, str)
        return m.group(0)

    def _get_file(self, src, dst):
        """Get file
        :param string src: Source file path
        :param string dst: Destination directory path

        :return: List of (src, dst)
        """
        if '*' in src:
            return self._change_to_tuple(self._get_file_with_wildcard(src, dst))
        else:
            return self._change_to_tuple([self._get_file_without_wildcard(src, dst)])

    @staticmethod
    def _create_missing_dirs(dst, dst_is_dir):
        if not dst_is_dir:
            dst = os.path.dirname(dst)
        if not os.path.exists(dst):
            os.makedirs(dst)

    def _get_file_without_wildcard(self, src, dst):
        dst_is_dir = dst.endswith(os.sep) or dst == '.'
        self._create_missing_dirs(dst, dst_is_dir)
        filename = os.path.basename(src)
        file_destination = os.path.join(dst, filename) if dst_is_dir else dst
        try:
            self._call_ssh_function(self._fsm_connection_client.files.get, src, file_destination)
        except IsADirectoryError as e:
            msg = f"""
            The destination path you have provided is an existing directory.
            If you want to copy into this directory, add a '/' to the path: '{os.path.join(dst, '')}/'
            """
            raise IsADirectoryError(msg) from e
        return (src, file_destination)

    def _get_file_with_wildcard(self, src, dst):
        out = self._fsm_connection_client.send_command("ls {}".format(src)).read_output().strip()
        files_list = out.splitlines()
        return_list = []
        for item in files_list:
            return_list.append(self._get_file(item, dst))
        return return_list

    def _put_file(self, src, dst):
        """Put file
        :param string src: Source path
        :param string dst: Destination path

        :return: List of (src, dst)
        """
        if '*' in src:
            return self._change_to_tuple(self._put_file_with_wildcard(src, dst))
        else:
            return self._change_to_tuple([self._put_file_without_wildcard(src, dst)])

    def _put_file_without_wildcard(self, src, dst):
        dst_is_dir = dst.endswith(os.sep) or dst == '.'
        source_file_name = os.path.basename(src)
        file_destination = os.path.join(dst, source_file_name) if dst_is_dir else dst
        try:
            self._call_ssh_function(self._fsm_connection_client.files.put, src, file_destination)
        except IsADirectoryError as e:
            msg = f'''\
            Source you`ve tried to copy is a directory. If you want to copy all of the content
            of this directory, use a wildcard like so: "{os.path.join(src, '*')}"
            '''
            raise IsADirectoryError(msg) from e
        except IOError as e:
            msg = f'If destination you`ve specified is a directory, please indicate it by ending the path with a backslash: "{os.path.join(dst, "")}"'
            raise IOError(msg) from e
        return (file_destination, src)

    def _put_file_with_wildcard(self, src, dst):
        absolute_path_to_dir = os.path.abspath(src)
        file_list = glob.glob(absolute_path_to_dir)
        return_list = []
        for item in file_list:
            file_destination = os.path.join(dst, os.path.basename(item))
            return_list.append(self._put_file(item, file_destination))
        return return_list

    def _get_directory(self, src, tar_output):
        main_dir = os.path.basename(os.path.normpath(src))
        full_path = os.path.join(tempfile.gettempdir(), 'copy_dir', main_dir)
        if os.path.exists(full_path):
            shutil.rmtree(full_path)
        self._fsm_connection_client.send_command(
            "tar -cvf {} {}".format(os.path.join(src, os.path.basename(tar_output)), src))
        if not os.path.exists(full_path):
            os.makedirs(full_path)
        dst = os.path.join(full_path, os.path.basename(tar_output))
        self._fsm_connection_client.files.get(os.path.join(src, os.path.basename(tar_output)), dst)

    def _change_to_tuple(self, src_dst_path):
        return list(zip(*src_dst_path))[0] if type(src_dst_path) is tuple else src_dst_path[0]

    def _get_partition_path(self, partition):
        if partition == 'active':
            return self._get_active_path()
        elif partition == 'passive':
            return self._get_passive_path()
        elif partition == 'planned':
            return os.path.join(self._get_passive_path(), 'planned')
        else:
            raise WrongPartition("Name should be: active, passive or planned.")

    def _get_active_path(self):
        return self._execute_ssh_command("readlink -f /ffs/run")

    def _get_passive_path(self):
        passive_path = self._execute_ssh_command("readlink -f /ffs/stb")
        if not search(".*fs[1-4]$", passive_path):
            passive_path = self._get_passive_partition_alternatively()
        return passive_path

    def _get_passive_partition_alternatively(self):
        active_partition_path = self._get_active_path()
        partitions_replace_dict = {'fs1': 'fs2', 'fs2': 'fs1', 'fs3': 'fs4', 'fs4': 'fs3'}
        pattern = re.compile("|".join(partitions_replace_dict.keys()))
        active_partition_fs = pattern.search(active_partition_path).group()
        passive_partition_fs = partitions_replace_dict[active_partition_fs]
        return active_partition_path.replace(active_partition_fs, passive_partition_fs)

    def _is_only_one_file(self, files):
        files = files.replace('\n', ' ')
        return True if len(files.split(' ')) == 1 else False

    def _call_ssh_function(self, ssh_function, *args, **kwargs):
        try:
            return ssh_function(*args, **kwargs)
        except RuntimeError as e:
            if str(e) != 'No open connection.':
                raise e
            else:
                self.teardown()
                self.setup()
                return ssh_function(*args, **kwargs)

    def _make_writeable_passive_partition(self):
        partition_path = self._get_partition_path("passive")
        self._execute_ssh_command("mount -o rw,remount %s" % partition_path)

    def _get_filedirectory_xml(self, partition_path):
        return self._execute_ssh_command('cat {}/FileDirectory.xml'.format(partition_path))
